// Accept whatever shape the form vendor sends and emit one neutral lead object.
// Everything downstream reads item.json.lead - nothing reads the raw body.
function pick(obj, keys) {
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null && String(obj[k]).trim() !== '') return String(obj[k]).trim();
  }
  return '';
}
return $input.all().map((item) => {
  const b = item.json.body || item.json;
  const lead = {
    email: pick(b, ['email', 'Email', 'email_address', 'work_email']).toLowerCase(),
    phone: pick(b, ['phone', 'Phone', 'phone_number', 'tel']),
    name: pick(b, ['name', 'full_name', 'Name', 'fullName']),
    company: pick(b, ['company', 'company_name', 'organisation', 'organization']),
    domain: pick(b, ['domain', 'website', 'company_website']),
    message: pick(b, ['message', 'notes', 'comments', 'how_can_we_help']),
    source: pick(b, ['source', 'utm_source']) || 'web_form',
    campaign: pick(b, ['campaign', 'utm_campaign']),
    consent_basis: b.consent === true || b.consent === 'true' ? 'consent' : (b.consent_basis || null),
    consent_recorded_at: b.consent === true || b.consent === 'true' ? new Date().toISOString() : (b.consent_recorded_at || null),
    requested_call: b.requested_call === true || /call|demo|quote/i.test(pick(b, ['message', 'interest'])),
    budget_stated: Number(b.budget || 0) > 0,
    budget_amount: Number(b.budget || 0),
    timeline_days: Number(b.timeline_days || 0),
    received_at: new Date().toISOString(),
    ip_hint: item.json.headers ? item.json.headers['x-forwarded-for'] || '' : ''
  };
  if (!lead.email && !lead.phone) {
    throw new Error('Form payload has neither email nor phone - reject rather than create a junk lead.');
  }
  return { json: { lead } };
});

// Build the request the rails expect. Missing fields are denied, not defaulted:
// the rails fail closed on purpose.
return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  return { json: Object.assign({}, item.json, { rails_request: {
    channel: 'email',
    purpose: 'first_response',
    contact_email: lead.email || '',
    contact_phone: lead.phone || '',
    contact_handle: lead.handle || '',
    inbound_message: lead.last_inbound_message || '',
    consent: { basis: lead.consent_basis || null, recorded_at: lead.consent_recorded_at || null },
    estimated_cost_usd: Number(lead.estimated_cost_usd || 0),
    workflow: $workflow.name
  } }) };
});

// The rails said no. Record it and stop. A denied action is never retried.
return $input.all().map((item) => ({ json: {
  blocked: true,
  code: item.json.code || 'denied',
  reason: item.json.reason || 'Safety rails denied this action.',
  contact: item.json.rails_request ? item.json.rails_request.contact_email : null,
  workflow: $workflow.name,
  at: new Date().toISOString()
} }));

