// Source of truth: logic/dedupe.js (unit tested in tests/dedupe.test.js).
const MATCH_THRESHOLDS = { merge: 0.9, review: 0.6 };
function normalizeEmail(email) {
  if (typeof email !== 'string' || !email.includes('@')) return '';
  let local = email.trim().toLowerCase().slice(0, email.lastIndexOf('@'));
  let domain = email.trim().toLowerCase().slice(email.lastIndexOf('@') + 1);
  const plus = local.indexOf('+');
  if (plus > 0) local = local.slice(0, plus);
  if (domain === 'gmail.com' || domain === 'googlemail.com') { local = local.split('.').join(''); domain = 'gmail.com'; }
  return local && domain ? local + '@' + domain : '';
}
function normalizePhone(phone) {
  const digits = String(phone || '').replace(/[^0-9]/g, '');
  return digits.length < 7 ? '' : digits.slice(-10);
}
return $input.all().map((item) => {
  const lead = item.json.lead;
  return { json: Object.assign({}, item.json, {
    match: { email_key: normalizeEmail(lead.email), phone_key: normalizePhone(lead.phone), thresholds: MATCH_THRESHOLDS }
  }) };
});

// Existing row wins on identity fields, new submission wins on freshness.
// We never overwrite a non-empty stored value with an empty new one.
const existing = $input.all().filter((i) => i.json && i.json.id);
const incoming = $('Dedupe Key').all()[0].json;
const lead = Object.assign({}, incoming.lead);
if (existing.length) {
  const e = existing[0].json;
  lead.id = e.id;
  lead.created_at = e.created_at;
  lead.is_new = false;
  for (const k of ['name', 'company', 'domain', 'phone', 'email']) {
    if (!lead[k] && e[k]) lead[k] = e[k];
  }
} else {
  lead.is_new = true;
  lead.created_at = new Date().toISOString();
}
lead.email_key = incoming.match.email_key;
lead.phone_key = incoming.match.phone_key;
return [{ json: { lead } }];

// Source of truth: logic/scoring.js (unit tested in tests/scoring.test.js).
const SCORING_WEIGHTS = {
  has_business_email: 15,
  company_size_11_50: 10,
  company_size_51_200: 15,
  company_size_200_plus: 20,
  budget_stated: 20,
  timeline_under_30d: 15,
  requested_call: 20,
  replied_within_1h: 10,
  competitor_page_view: 10,
  free_email_domain: -10,
  student_or_jobseeker: -25,
  outside_service_area: -15
};

const SCORE_BANDS = [
  { name: 'hot', min: 60 },
  { name: 'warm', min: 35 },
  { name: 'cold', min: 15 },
  { name: 'junk', min: 0 }
];

const FREE_EMAIL_DOMAINS = ['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','aol.com','icloud.com','proton.me','protonmail.com','gmx.com','mail.com'];

function bandFor(score) {
  for (const b of SCORE_BANDS) { if (score >= b.min) return b.name; }
  return 'junk';
}

function scoreLead(l) {
  const reasons = [];
  let raw = 0;
  const add = (sig) => {
    const pts = SCORING_WEIGHTS[sig];
    if (typeof pts !== 'number') return;
    raw += pts;
    reasons.push(sig + ' ' + (pts > 0 ? '+' : '') + pts);
  };
  const email = typeof l.email === 'string' ? l.email.trim().toLowerCase() : '';
  const domain = email.includes('@') ? email.split('@').pop() : '';
  const free = domain !== '' && FREE_EMAIL_DOMAINS.includes(domain);
  if (email && !free) add('has_business_email');
  if (free) add('free_email_domain');
  const size = Number(l.company_size);
  if (Number.isFinite(size)) {
    if (size >= 200) add('company_size_200_plus');
    else if (size >= 51) add('company_size_51_200');
    else if (size >= 11) add('company_size_11_50');
  }
  if (l.budget_stated === true || Number(l.budget_amount) > 0) add('budget_stated');
  const days = Number(l.timeline_days);
  if (Number.isFinite(days) && days > 0 && days <= 30) add('timeline_under_30d');
  if (l.requested_call === true) add('requested_call');
  if (l.replied_within_minutes !== undefined && Number(l.replied_within_minutes) <= 60) add('replied_within_1h');
  if (l.viewed_competitor_page === true) add('competitor_page_view');
  if (l.is_student === true || l.is_jobseeker === true) add('student_or_jobseeker');
  if (l.in_service_area === false) add('outside_service_area');
  const score = Math.max(0, Math.min(100, raw));
  return { score, band: bandFor(score), reasons };
}

return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  const s = scoreLead(lead);
  return { json: Object.assign({}, item.json, {
    lead: Object.assign({}, lead, { score: s.score, band: s.band, score_reasons: s.reasons })
  }) };
});

// Source of truth: logic/crm.js. Set CRM_ADAPTER (env var) to the CRM you run.
// Supported: 'generic' (any REST CRM), 'hubspot', 'gohighlevel', 'pipedrive'.
// See docs/CRM-MAPPING.md before adding a new one.
const CRM_ADAPTERS = ['generic', 'hubspot', 'gohighlevel', 'pipedrive'];
const CRM_ADAPTER = $env.CRM_ADAPTER || 'generic';

function nonEmpty(o) {
  const out = {};
  for (const k of Object.keys(o)) {
    const v = o[k];
    if (v !== null && v !== undefined && v !== '') out[k] = v;
  }
  return out;
}
function splitName(name) {
  const n = (name || '').trim();
  if (!n) return { first: '', last: '' };
  const p = n.split(/\s+/);
  return { first: p[0], last: p.slice(1).join(' ') };
}
function toCrmPayload(l) {
  const name = splitName(l.name);
  const tags = Array.isArray(l.tags) ? l.tags.slice() : [];
  if (l.band) tags.push('score:' + l.band);
  if (l.source) tags.push('source:' + l.source);
  if (CRM_ADAPTER === 'hubspot') {
    return { properties: nonEmpty({ email: l.email, phone: l.phone, firstname: name.first,
      lastname: name.last, company: l.company, hs_lead_status: l.band === 'hot' ? 'OPEN' : 'NEW',
      lifecyclestage: 'lead', lead_score_custom: l.score,
      lead_score_reasons: (l.score_reasons || []).join('; ') }) };
  }
  if (CRM_ADAPTER === 'gohighlevel') {
    return nonEmpty({ email: l.email, phone: l.phone, firstName: name.first, lastName: name.last,
      companyName: l.company, source: l.source, tags: tags, customFields: [
        { key: 'lead_score', field_value: String(l.score === undefined ? '' : l.score) },
        { key: 'lead_band', field_value: l.band || '' },
        { key: 'consent_basis', field_value: l.consent_basis || '' } ] });
  }
  if (CRM_ADAPTER === 'pipedrive') {
    return nonEmpty({ name: l.name, org_name: l.company, label: l.band, visible_to: '3' });
  }
  return nonEmpty({ email: l.email, phone: l.phone, name: l.name, company: l.company,
    domain: l.domain, source: l.source, campaign: l.campaign, score: l.score, band: l.band,
    score_reasons: l.score_reasons, consent_basis: l.consent_basis, tags: tags, notes: l.notes });
}

return $input.all().map((item) => {
  const lead = Object.assign({ source: '%s' }, item.json.lead || item.json);
  return { json: Object.assign({}, item.json, {
    lead,
    crm_adapter: CRM_ADAPTER,
    crm_payload: toCrmPayload(lead),
    crm_match_value: lead.email || lead.phone || lead.name || ''
  }) };
});

